<?php
namespace Tests\Feature;
use App\Models\User;
use App\Modules\Tenancy\Models\Officine;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Laravel\Sanctum\Sanctum;
use Tests\TestCase;
class MissionVisitsTest extends TestCase {
 use RefreshDatabase;
 private User $admin;private User $lead;private Officine $office;private int $mission;private int $assignment;
 protected function setUp():void{parent::setUp();$this->admin=User::create(['name'=>'Admin visite','email'=>'admin-visit@example.test','password'=>'Fictional12345']);$this->lead=User::create(['name'=>'Responsable visite','email'=>'lead-visit@example.test','password'=>'Fictional12345']);$this->lead->forceFill(['is_support_staff'=>true])->save();$this->office=Officine::create(['name'=>'Visite','slug'=>'visit-office','status'=>'active']);DB::table('officine_user')->insert(['user_id'=>$this->admin->id,'officine_id'=>$this->office->id,'is_admin'=>true,'is_active'=>true,'permissions'=>'[]']);$q=DB::table('support_requests')->insertGetId(['officine_id'=>$this->office->id,'created_by'=>$this->admin->id,'reference'=>'VIS-REQ','request_key'=>'visit-request-000001','status'=>'submitted']);$this->mission=DB::table('support_missions')->insertGetId(['support_request_id'=>$q,'proposed_by'=>$this->lead->id,'title'=>'Mission visites','scope'=>'Suivi','starts_on'=>now()->subDays(10)->toDateString(),'ends_on'=>now()->addDays(30)->toDateString(),'status'=>'active']);$this->assignment=DB::table('officine_support_assignments')->insertGetId(['officine_id'=>$this->office->id,'user_id'=>$this->lead->id,'proposed_by'=>$this->admin->id,'scope'=>'Mission visites','permissions'=>json_encode(['accompagnement.read','accompagnement.write']),'starts_on'=>now()->subDay()->toDateString(),'ends_on'=>now()->addDays(30)->toDateString(),'status'=>'approved','request_key'=>'visit-assignment-00001','created_at'=>now(),'updated_at'=>now()]);DB::table('support_mission_team')->insert(['mission_id'=>$this->mission,'assignment_id'=>$this->assignment,'role'=>'lead','status'=>'approved','proposed_by'=>$this->admin->id]);$this->withHeader('X-Officine-ID',(string)$this->office->id);Sanctum::actingAs($this->lead);}
 private function base():string{return '/api/v1/support/missions/'.$this->mission.'/visits';}
 private function data():array{return ['request_key'=>'visit-browser-key-0000001','title'=>'Atelier fictif','mode'=>'remote','place'=>'Lien privé fictif','starts_at'=>now()->addDays(2)->toIso8601String(),'ends_at'=>now()->addDays(2)->addHour()->toIso8601String(),'confirmed'=>true];}
 private function create():int{return $this->postJson($this->base(),$this->data())->assertCreated()->json('id');}
 private function change(int $visit,string $action,int $version,array $more=[]){return $this->postJson($this->base().'/'.$visit.'/transition',$more+['action'=>$action,'version'=>$version,'reason'=>'Motif partagé','confirmed'=>true]);}
 private function confirmedVisit():int{$v=$this->create();$this->change($v,'propose',1)->assertOk();Sanctum::actingAs($this->admin);$this->change($v,'confirm',2)->assertOk();Sanctum::actingAs($this->lead);return $v;}
 private function reportData():array{return ['visit_version'=>3,'actual_starts_at'=>now()->subHours(3)->toIso8601String(),'actual_ends_at'=>now()->subHours(2)->toIso8601String(),'attendance'=>'Participants fictifs','activities'=>'Activités réalisées','decisions'=>'Décisions partagées','next_steps'=>'Suivi à convenir','confirmed'=>true];}
 public function test_draft_is_hidden_from_office_including_audit_and_only_admin_confirms():void{
  $v=$this->create();Sanctum::actingAs($this->admin);$this->getJson($this->base())->assertOk()->assertJsonCount(0,'data');$this->getJson('/api/v1/officine/journal?action=support.visit.draft_created')->assertJsonCount(0,'data');$this->change($v,'confirm',1)->assertNotFound();Sanctum::actingAs($this->lead);$this->change($v,'propose',1)->assertOk();$this->change($v,'confirm',2)->assertForbidden();Sanctum::actingAs($this->admin);$this->getJson($this->base())->assertJsonCount(1,'data');$this->change($v,'confirm',2)->assertOk();$this->change($v,'confirm',2)->assertConflict();
 }
 public function test_bad_dates_period_and_unaccepted_mission_are_rejected():void{
  $d=$this->data();$this->postJson($this->base(),array_replace($d,['ends_at'=>$d['starts_at']]))->assertUnprocessable();$this->postJson($this->base(),array_replace($d,['starts_at'=>now()->addDays(40)->toIso8601String(),'ends_at'=>now()->addDays(40)->addHour()->toIso8601String()]))->assertUnprocessable();DB::table('support_missions')->update(['status'=>'accepted']);$this->postJson($this->base(),$d)->assertConflict();
 }
 public function test_reschedule_preserves_old_dates_and_creates_unconfirmed_occurrence():void{
  $v=$this->confirmedVisit();$old=DB::table('support_visits')->where('id',$v)->first();$new=array_replace($this->data(),['starts_at'=>now()->addDays(3)->toIso8601String(),'ends_at'=>now()->addDays(3)->addHour()->toIso8601String()]);$this->change($v,'reschedule',3,$new)->assertOk();$this->assertDatabaseHas('support_visits',['id'=>$v,'status'=>'rescheduled','starts_at'=>$old->starts_at,'ends_at'=>$old->ends_at]);$this->assertDatabaseHas('support_visits',['previous_id'=>$v,'status'=>'proposed']);$this->change($v,'reschedule',3,$new)->assertConflict();$this->assertDatabaseCount('support_visits',2);
 }
 public function test_reports_are_frozen_and_office_only_sees_shared_versions():void{
  $v=$this->confirmedVisit();$url=$this->base().'/'.$v.'/reports';$report=$this->postJson($url,$this->reportData())->assertCreated()->json('id');Sanctum::actingAs($this->admin);$this->getJson($this->base())->assertJsonCount(0,'data.0.reports');$this->getJson('/api/v1/officine/journal?action=support.visit.report_draft_created')->assertJsonCount(0,'data');Sanctum::actingAs($this->lead);
  $this->patchJson($url.'/'.$report,$this->reportData()+['version'=>1])->assertOk();$decision=$url.'/'.$report.'/decision';$this->postJson($decision,['version'=>2,'action'=>'submit','confirmed'=>true])->assertOk();$this->patchJson($url.'/'.$report,$this->reportData()+['version'=>3])->assertConflict();$this->postJson($decision,['version'=>3,'action'=>'share','confirmed'=>true])->assertOk();$this->postJson($decision,['version'=>3,'action'=>'share','confirmed'=>true])->assertConflict();Sanctum::actingAs($this->admin);$this->getJson($this->base())->assertJsonCount(1,'data.0.reports')->assertJsonPath('data.0.reports.0.activities','Activités réalisées');Sanctum::actingAs($this->lead);$this->postJson($url,$this->reportData())->assertCreated();$this->assertDatabaseCount('support_visit_reports',2);
 }
 public function test_completion_needs_shared_report_and_actual_dates_cannot_be_future():void{
  $v=$this->confirmedVisit();$this->change($v,'complete',3)->assertConflict();$url=$this->base().'/'.$v.'/reports';$this->postJson($url,array_replace($this->reportData(),['actual_ends_at'=>now()->addHour()->toIso8601String()]))->assertUnprocessable();$r=$this->postJson($url,$this->reportData())->assertCreated()->json('id');$this->postJson($url.'/'.$r.'/decision',['version'=>1,'action'=>'submit','confirmed'=>true])->assertOk();$this->postJson($url.'/'.$r.'/decision',['version'=>2,'action'=>'share','confirmed'=>true])->assertOk();$this->change($v,'complete',3)->assertOk();$this->assertDatabaseHas('support_visits',['id'=>$v,'status'=>'completed']);
 }
 public function test_revocation_and_cross_office_access_are_denied():void{
  $v=$this->create();DB::table('officine_support_assignments')->where('id',$this->assignment)->update(['status'=>'revoked']);$this->getJson($this->base())->assertForbidden();$this->change($v,'propose',1)->assertForbidden();Sanctum::actingAs($this->admin);$other=Officine::create(['name'=>'Other','slug'=>'visit-other','status'=>'active']);DB::table('officine_user')->insert(['user_id'=>$this->admin->id,'officine_id'=>$other->id,'is_admin'=>true,'is_active'=>true,'permissions'=>'[]']);$this->withHeader('X-Officine-ID',(string)$other->id)->getJson($this->base())->assertNotFound();
 }
 public function test_cancelling_an_unpublished_draft_does_not_publish_its_metadata():void{
  $v=$this->create();$this->change($v,'cancel',1)->assertOk();Sanctum::actingAs($this->admin);$this->getJson($this->base())->assertJsonCount(0,'data');$this->getJson('/api/v1/officine/journal?action=support.visit.draft_cancelled')->assertJsonCount(0,'data');$this->change($v,'cancel',2)->assertNotFound();
 }
 public function test_creation_key_replay_never_duplicates_visit_or_audit():void{
  $d=$this->data();$v=$this->postJson($this->base(),$d)->assertCreated()->json('id');$this->postJson($this->base(),$d)->assertOk()->assertJsonPath('id',$v);$this->postJson($this->base(),array_replace($d,['title'=>'Autre objet']))->assertConflict();$this->assertDatabaseCount('support_visits',1);$this->assertSame(1,DB::table('tenant_audit_logs')->where('action','support.visit.draft_created')->count());
 }
}
